"def test_claim_users_with_mixed_input(enterprise, enterprise_mocks):
    result = enterprise.claim_users({
        'usrFakeUserId': 'managed',
        'someone@example.com': 'unmanaged',
        'another@example.com': 'managed'
    })
    assert isinstance(result, ManageUsersResponse)
    assert enterprise_mocks.claim_users.call_count == 1
    expected_payload = {
        'users': [
            {'id': 'usrFakeUserId', 'state': 'managed'},
            {'email': 'someone@example.com', 'state': 'unmanaged'},
            {'email': 'another@example.com', 'state': 'managed'}
        ]
    }
    assert enterprise_mocks.claim_users.last_request.json() == expected_payload"

"def test_delete_enterprise_only_base(api, base, monkeypatch):
    """
    Test that Base.delete() raises an exception for non-enterprise plans.
    """
    class MockResponse:
        def __init__(self, status_code):
            self.status_code = status_code

    def mock_delete_404(*args, **kwargs):
        return MockResponse(404)

    def mock_delete_200(*args, **kwargs):
        return MockResponse(200)

    monkeypatch.setattr(base.api, 'delete', mock_delete_404)
    with pytest.raises(Exception) as excinfo:
        base.delete()
    assert "Base.delete() requires an enterprise billing plan" in str(excinfo.value)

    monkeypatch.setattr(base.api, 'delete', mock_delete_200)
    base.delete()  # Should not raise an exception"

"import pytest
from pyairtable.api.enterprise import UserInfo

def test_users_with_mixed_input(enterprise, monkeypatch):
    def mock_api_get(url, params):
        assert url == f'{enterprise.url}/users'
        assert params == {
            'id': ['usr1'],
            'email': ['user2@example.com', 'nonexistent@example.com'],
            'include': ['collaborations']
        }
        return {
            'users': [
                {
                    'id': 'usr1',
                    'email': 'user1@example.com',
                    'name': 'User 1',
                    'state': 'provisioned',
                    'isSsoRequired': False,
                    'isTwoFactorAuthEnabled': False
                },
                {
                    'id': 'usr2',
                    'email': 'user2@example.com',
                    'name': 'User 2',
                    'state': 'provisioned',
                    'isSsoRequired': False,
                    'isTwoFactorAuthEnabled': False
                },
            ]
        }

    monkeypatch.setattr(enterprise.api, 'get', mock_api_get)

    search_for = ['usr1', 'user2@example.com', 'nonexistent@example.com']
    results = enterprise.users(search_for)

    assert len(results) == 2
    assert all(isinstance(user, UserInfo) for user in results)
    assert {user.id for user in results} == {'usr1', 'usr2'}

    for user in results:
        assert user.state == 'provisioned'
        assert user.email in ['user1@example.com', 'user2@example.com']
        assert user.name in ['User 1', 'User 2']"

"def test_options_to_json_and_params_new_features():
    options = {
        'fields': ['Name', 'Phone', 'Name'],  # Duplicate field
        'max_records': 0,  # Should be removed
        'sort': ['Name', '-Age'],
        'use_field_ids': True,
        'view': 'Grid view',
        'user_locale': 'en-US'
    }

    expected_json = {
        'fields': ['Name', 'Phone'],  # Duplicates removed
        'sort': [
            {'field': 'Name', 'direction': 'asc'},
            {'field': 'Age', 'direction': 'desc'}
        ],
        'returnFieldsByFieldId': True,
        'view': 'Grid view'
    }

    expected_params = {
        'userLocale': 'en-US'
    }

    result_json, result_params = options_to_json_and_params(options)

    assert result_json == expected_json
    assert result_params == expected_params"

"import pytest
from requests.auth import HTTPBasicAuth
import netrc
from urllib.parse import urlparse
from scrapyd_client.utils import get_auth

@pytest.mark.parametrize('url,username,password,expected', [
    ('http://localhost:6800', 'user', 'pass', ('user', 'pass')),
    ('http://localhost:6800', 'user', None, None),
    ('http://localhost:6800', None, 'pass', None),
    ('http://example.com', None, None, ('netrc_user', 'netrc_pass')),
])
def test_get_auth_with_changes(url, username, password, expected, monkeypatch):
    def mock_netrc():
        class MockNetrc:
            def authenticators(self, host):
                return ('netrc_user', None, 'netrc_pass') if host == 'example.com' else None
        return MockNetrc()

    monkeypatch.setattr(netrc, 'netrc', mock_netrc)

    result = get_auth(url, username, password)

    if expected is None:
        assert result is None
    else:
        assert isinstance(result, HTTPBasicAuth)
        assert result.username == expected[0]
        assert result.password == expected[1]"
